SELECT sum(bytes * if(sampling_rate = 0, 1, sampling_rate)) AS traffic
FROM $table
WHERE $timeFilter
  AND ${ip:singlequote} != ''
  AND (
        (${role:singlequote} = 'any' AND (
            ipToStr(src_addr, etype) = ${ip:singlequote}
         OR ipToStr(dst_addr, etype) = ${ip:singlequote}
        ))
     OR (${role:singlequote} = 'src' AND ipToStr(src_addr, etype) = ${ip:singlequote})
     OR (${role:singlequote} = 'dst' AND ipToStr(dst_addr, etype) = ${ip:singlequote})
  )

SELECT sum(packets * if(sampling_rate = 0, 1, sampling_rate)) AS packets
FROM $table
WHERE $timeFilter
  AND ${ip:singlequote} != ''
  AND (
        (${role:singlequote} = 'any' AND (
            ipToStr(src_addr, etype) = ${ip:singlequote}
         OR ipToStr(dst_addr, etype) = ${ip:singlequote}
        ))
     OR (${role:singlequote} = 'src' AND ipToStr(src_addr, etype) = ${ip:singlequote})
     OR (${role:singlequote} = 'dst' AND ipToStr(dst_addr, etype) = ${ip:singlequote})
  )

SELECT count() AS flows
FROM $table
WHERE $timeFilter
  AND ${ip:singlequote} != ''
  AND (
        (${role:singlequote} = 'any' AND (
            ipToStr(src_addr, etype) = ${ip:singlequote}
         OR ipToStr(dst_addr, etype) = ${ip:singlequote}
        ))
     OR (${role:singlequote} = 'src' AND ipToStr(src_addr, etype) = ${ip:singlequote})
     OR (${role:singlequote} = 'dst' AND ipToStr(dst_addr, etype) = ${ip:singlequote})
  )

SELECT uniqExact(peer) AS peers
FROM
(
    SELECT
        if(
            ipToStr(src_addr, etype) = ${ip:singlequote},
            ipToStr(dst_addr, etype),
            ipToStr(src_addr, etype)
        ) AS peer
    FROM $table
    WHERE $timeFilter
      AND ${ip:singlequote} != ''
      AND (
            (${role:singlequote} = 'any' AND (
                ipToStr(src_addr, etype) = ${ip:singlequote}
             OR ipToStr(dst_addr, etype) = ${ip:singlequote}
            ))
         OR (${role:singlequote} = 'src' AND ipToStr(src_addr, etype) = ${ip:singlequote})
         OR (${role:singlequote} = 'dst' AND ipToStr(dst_addr, etype) = ${ip:singlequote})
      )
)
WHERE peer != ''
